DROP TABLE IF EXISTS `expense_policy_standard`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `expense_policy_standard` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `tenant_id` bigint DEFAULT NULL COMMENT '租户ID',
  `policy_id` bigint NOT NULL COMMENT '关联政策ID',
  `standard_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '标准类型：AMOUNT-金额标准 QUOTA-限额 RATE-比例',
  `standard_key` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '标准项标识（如 TRAVEL-ECONOMY）',
  `standard_value_min` decimal(18,2) DEFAULT NULL COMMENT '最小值',
  `standard_value_max` decimal(18,2) DEFAULT NULL COMMENT '最大值',
  `standard_unit` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '单位：元/天/次/人',
  `level_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '级别类型：EMPLOYEE_LEVEL/POSITION/DEPARTMENT',
  `level_value` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '级别值',
  `overtime_action` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'WARN' COMMENT '超标处理：WARN-警告 BLOCK-阻止 EXTRAAUTH-附加审批',
  `overtime_auth_level` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '超标附加审批级别',
  `remark` varchar(256) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `employee_level` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '员工级别',
  `position` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '职位',
  `domestic_transport` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '国内交通标准JSON',
  `international_transport` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '国际交通标准JSON',
  `create_by` bigint DEFAULT NULL COMMENT '创建人',
  `update_by` bigint DEFAULT NULL COMMENT '更新人',
  `del_flag` tinyint DEFAULT '0' COMMENT '删除标记',
  `domestic_accommodation` decimal(18,2) DEFAULT NULL COMMENT '国内住宿标准',
  `international_accommodation` decimal(18,2) DEFAULT NULL COMMENT '国外住宿标准',
  `domestic_meal` decimal(18,2) DEFAULT NULL COMMENT '国内餐费标准',
  `international_meal` decimal(18,2) DEFAULT NULL COMMENT '国外餐费标准',
  `domestic_other` decimal(18,2) DEFAULT NULL COMMENT '国内其他标准',
  `international_other` decimal(18,2) DEFAULT NULL COMMENT '国外其他标准',
  `city_tier1_factor` decimal(18,4) DEFAULT NULL COMMENT '城市1档系数',
  `city_tier2_factor` decimal(18,4) DEFAULT NULL COMMENT '城市2档系数',
  `city_tier3_factor` decimal(18,4) DEFAULT NULL COMMENT '城市3档系数',
  `effective_date` date DEFAULT NULL COMMENT '生效日期',
  `std_status` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '标准状态',
  `city_tier_1_factor` decimal(18,4) DEFAULT NULL COMMENT '城市1档系数',
  `city_tier_2_factor` decimal(18,4) DEFAULT NULL COMMENT '城市2档系数',
  `city_tier_3_factor` decimal(18,4) DEFAULT NULL COMMENT '城市3档系数',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`),
  KEY `idx_policy_id` (`policy_id`),
  KEY `idx_standard_type_key` (`standard_type`,`standard_key`)
) ENGINE=InnoDB AUTO_INCREMENT=50 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='费用标准配置表（合并差旅标准）';
